customInputs.expression:
=a!localVariables(
  local!idExistente: tostring(a!defaultValue(index(index(index(pv!sol,"datosCompletosSolicitud",null),"datosBasicosSolicitud",null),"idgestionsgc",null),"")),
  local!codPerfil: tostring(a!defaultValue(index(index(pv!sol,"datosPerfilesPca",null),"codperfil",null),"")),
  /* Decisión funcional (Excel 18): POSPONER de Autorización también da de alta la gestión SGC */
  /* Paridad SCA (nodo Posponer y caducidad): solo se da de alta la gestión SGC si aún no existe idGestionSGC y el perfil es CE_RM */
  if(
    or(and(a!isNotNullOrEmpty(local!idExistente), local!idExistente<>"0"), local!codPerfil<>"CE_RM"),
    a!map(codigo: 0, idGestionSGC: if(local!idExistente="0", null, local!idExistente), omitido: true),
    rule!SCA2_posponerGestionSGC(sol: pv!sol, tipoAccion: a!defaultValue(pv!tipoAccion,"ACCADM"), detalleOficina: pv!detalleOficina, fecDispoVeh: pv!fecDispoVeh, datosAutorizacion: pv!datosAutorizacion, soloPayload: false)
  )
)

=a!localVariables(
  local!docs: reject(fn!isnull, a!defaultValue(pv!listaNombreDocs, {})),
  /* Paridad SCA (PM Acciones Administrativas: Caducada? → Subir Docs Documentum BBDD antes de Posponer y caducidad): los adjuntos de la acción se suben a GD/BBDD CORE al POSPONER para que RETOMAR y el Detalle los muestren entregados */
  if(
    a!isNullOrEmpty(local!docs),
    a!map(success: true, omitido: true, numDocumentos: 0),
    rule!SCA2_subirDocumentosGD(codSolicitud: pv!idSolicitud, listaNombreDocs: local!docs, tipoGestion: a!defaultValue(pv!tipoAccion,"ACCADM"), nuuma: a!defaultValue(pv!nuuma, index(index(pv!sol,"datosPerfilesPca",null),"nuuma",null)))
  )
)
